import React, { useState } from 'react';
import { Upload, Button, message, Modal, Image, Typography, Space, Tag, Progress } from 'antd';
import { 
  UploadOutlined, 
  EyeOutlined, 
  DeleteOutlined, 
  FileTextOutlined,
  FileImageOutlined,
  FilePdfOutlined,
  FileWordOutlined,
  FileExcelOutlined,
  FileOutlined
} from '@ant-design/icons';
import { fileService } from '../../services/fileService';

const { Text } = Typography;

const FileUpload = ({
  multiple = true,
  maxCount = 5,
  accept = '*',
  listType = 'text',
  showPreview = true,
  showProgress = true,
  onFileChange,
  onFileRemove,
  value = [],
  disabled = false,
  uploadText = 'Upload Files',
  ...props
}) => {
  const [fileList, setFileList] = useState(value || []);
  const [previewVisible, setPreviewVisible] = useState(false);
  const [previewFile, setPreviewFile] = useState(null);
  const [uploading, setUploading] = useState(false);

  const getFileIcon = (file) => {
    const type = file.type || '';
    if (type.startsWith('image/')) return <FileImageOutlined />;
    if (type.includes('pdf')) return <FilePdfOutlined />;
    if (type.includes('word') || type.includes('document')) return <FileWordOutlined />;
    if (type.includes('sheet') || type.includes('excel')) return <FileExcelOutlined />;
    return <FileOutlined />;
  };

  const getFileTypeColor = (file) => {
    const type = file.type || '';
    if (type.startsWith('image/')) return 'blue';
    if (type.includes('pdf')) return 'red';
    if (type.includes('word') || type.includes('document')) return 'blue';
    if (type.includes('sheet') || type.includes('excel')) return 'green';
    return 'default';
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleUpload = async (file) => {
    setUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      
      const response = await fileService.uploadFile(formData);
      
      const newFile = {
        uid: file.uid,
        name: file.name,
        status: 'done',
        url: response.url,
        response: response,
        size: file.size,
        type: file.type
      };

      const newFileList = [...fileList, newFile];
      setFileList(newFileList);
      
      if (onFileChange) {
        onFileChange(newFileList);
      }

      message.success(`${file.name} uploaded successfully`);
      return false; // Prevent default upload
    } catch (error) {
      message.error(`Failed to upload ${file.name}`);
      console.error('Upload error:', error);
      return false;
    } finally {
      setUploading(false);
    }
  };

  const handleRemove = async (file) => {
    try {
      if (file.url) {
        await fileService.deleteFile(file.url);
      }
      
      const newFileList = fileList.filter(item => item.uid !== file.uid);
      setFileList(newFileList);
      
      if (onFileChange) {
        onFileChange(newFileList);
      }

      if (onFileRemove) {
        onFileRemove(file);
      }

      message.success('File removed successfully');
    } catch (error) {
      message.error('Failed to remove file');
      console.error('Remove error:', error);
    }
  };

  const handlePreview = async (file) => {
    if (!file.url && !file.preview) {
      file.preview = await getBase64(file.originFileObj);
    }

    setPreviewFile(file);
    setPreviewVisible(true);
  };

  const getBase64 = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result);
      reader.onerror = error => reject(error);
    });
  };

  const uploadProps = {
    name: 'file',
    multiple,
    accept,
    fileList,
    beforeUpload: handleUpload,
    onRemove: handleRemove,
    onPreview: showPreview ? handlePreview : undefined,
    disabled,
    showUploadList: {
      showPreviewIcon: showPreview,
      showRemoveIcon: !disabled,
      showDownloadIcon: false,
    },
    ...props
  };

  const renderFileList = () => {
    if (listType === 'picture-card') {
      return (
        <Upload {...uploadProps}>
          {fileList.length >= maxCount ? null : (
            <div>
              <UploadOutlined />
              <div style={{ marginTop: 8 }}>{uploadText}</div>
            </div>
          )}
        </Upload>
      );
    }

    return (
      <div>
        <Upload {...uploadProps}>
          <Button 
            icon={<UploadOutlined />} 
            disabled={disabled || fileList.length >= maxCount}
            loading={uploading}
          >
            {uploadText}
          </Button>
        </Upload>
        
        {fileList.length > 0 && (
          <div style={{ marginTop: 16 }}>
            {fileList.map((file, index) => (
              <div 
                key={file.uid || index}
                style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  padding: '8px 12px',
                  border: '1px solid #d9d9d9',
                  borderRadius: '6px',
                  marginBottom: '8px',
                  backgroundColor: '#fafafa'
                }}
              >
                <div style={{ marginRight: 12, fontSize: '16px' }}>
                  {getFileIcon(file)}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
                    {file.name}
                  </div>
                  <Space size="small">
                    <Tag color={getFileTypeColor(file)} size="small">
                      {file.type?.split('/')[1]?.toUpperCase() || 'FILE'}
                    </Tag>
                    <Text type="secondary" style={{ fontSize: '12px' }}>
                      {formatFileSize(file.size)}
                    </Text>
                    {file.status === 'uploading' && showProgress && (
                      <Progress 
                        percent={file.percent || 0} 
                        size="small" 
                        style={{ width: '100px' }}
                      />
                    )}
                  </Space>
                </div>
                <Space>
                  {showPreview && (
                    <Button 
                      type="text" 
                      icon={<EyeOutlined />} 
                      size="small"
                      onClick={() => handlePreview(file)}
                    />
                  )}
                  {!disabled && (
                    <Button 
                      type="text" 
                      icon={<DeleteOutlined />} 
                      size="small"
                      danger
                      onClick={() => handleRemove(file)}
                    />
                  )}
                </Space>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div>
      {renderFileList()}
      
      <Modal
        open={previewVisible}
        title="File Preview"
        footer={null}
        onCancel={() => setPreviewVisible(false)}
        width={800}
      >
        {previewFile && (
          <div>
            {previewFile.type?.startsWith('image/') ? (
              <Image
                alt={previewFile.name}
                style={{ width: '100%' }}
                src={previewFile.url || previewFile.preview}
              />
            ) : (
              <div style={{ textAlign: 'center', padding: '40px' }}>
                <div style={{ fontSize: '48px', marginBottom: '16px' }}>
                  {getFileIcon(previewFile)}
                </div>
                <Text strong>{previewFile.name}</Text>
                <br />
                <Text type="secondary">
                  {formatFileSize(previewFile.size)} • {previewFile.type}
                </Text>
                <br />
                <Button 
                  type="primary" 
                  href={previewFile.url} 
                  target="_blank"
                  style={{ marginTop: '16px' }}
                >
                  Download File
                </Button>
              </div>
            )}
          </div>
        )}
      </Modal>
    </div>
  );
};

export default FileUpload;

