import React, { useState, useEffect } from 'react';
import IntegrationTest from '../components/IntegrationTest';
import { 
  Card, 
  Row, 
  Col, 
  Statistic, 
  Button, 
  Table, 
  Tag, 
  Space, 
  Typography,
  Timeline,
  Avatar,
  Progress,
  Badge,
  Empty,
  Spin,
  Alert
} from 'antd';
import { 
  FileAddOutlined, 
  UserOutlined, 
  DollarOutlined, 
  ClockCircleOutlined,
  CheckCircleOutlined,
  CarOutlined,
  ContainerOutlined,
  CalculatorOutlined,
  CreditCardOutlined,
  PlusOutlined,
  EyeOutlined,
  GlobalOutlined,
  CheckCircleFilled,
  ClockCircleFilled,
  ExclamationCircleFilled,
  SyncOutlined,
  FileTextOutlined
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import apiService from '../services/api';

const { Title, Text } = Typography;

const DashboardPage = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [dashboardData, setDashboardData] = useState({
    stats: {
      totalJobs: 0,
      activeShipments: 0,
      totalClients: 0,
      revenueThisMonth: 0,
      workflowStatuses: {}
    },
    recentActivities: [],
    recentShipments: []
  });

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const [statsResponse, recentShipmentsResponse] = await Promise.all([
        apiService.getDashboardStats(),
        apiService.getRecentShipments(5)
      ]);

      setDashboardData({
        stats: statsResponse.stats,
        recentActivities: statsResponse.recentActivities || [],
        recentShipments: recentShipmentsResponse.shipments || []
      });
    } catch (error) {
      console.error('Error loading dashboard data:', error);
      console.error('Error details:', {
        message: error.message,
        response: error.response?.data,
        status: error.response?.status,
        url: error.config?.url
      });
      setError(`Failed to load dashboard data: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Clearing agent statistics
  const stats = [
    {
      title: 'Total Jobs',
      value: dashboardData.stats.totalJobs,
      prefix: <FileAddOutlined />,
      color: '#1890ff',
      suffix: ''
    },
    {
      title: 'Active Shipments',
      value: dashboardData.stats.activeShipments,
      prefix: <ContainerOutlined />,
      color: '#faad14',
      suffix: ''
    },
    {
      title: 'Total Clients',
      value: dashboardData.stats.totalClients,
      prefix: <UserOutlined />,
      color: '#52c41a',
      suffix: ''
    },
    {
      title: 'Revenue This Month',
      value: dashboardData.stats.revenueThisMonth,
      prefix: <DollarOutlined />,
      suffix: 'GHS'
    }
  ];

  // Recent shipments
  const recentShipments = dashboardData.recentShipments;

  // Workflow status counts
  const workflowStatuses = [
    { status: 'SUBMITTED', count: dashboardData.stats.workflowStatuses.SUBMITTED || 0, color: '#1890ff', icon: <FileAddOutlined /> },
    { status: 'UNDER_REVIEW', count: dashboardData.stats.workflowStatuses.UNDER_REVIEW || 0, color: '#00072D', icon: <ClockCircleOutlined /> },
    { status: 'QUOTED', count: dashboardData.stats.workflowStatuses.QUOTED || 0, color: '#722ed1', icon: <CalculatorOutlined /> },
    { status: 'AWAITING_PAYMENT', count: dashboardData.stats.workflowStatuses.AWAITING_PAYMENT || 0, color: '#eb2f96', icon: <CreditCardOutlined /> },
    { status: 'CLEARING', count: dashboardData.stats.workflowStatuses.CLEARING || 0, color: '#52c41a', icon: <SyncOutlined /> },
    { status: 'DELIVERED', count: dashboardData.stats.workflowStatuses.DELIVERED || 0, color: '#52c41a', icon: <CheckCircleOutlined /> }
  ];

  // Recent activities
  const recentActivities = dashboardData.recentActivities;
 

  const getStatusColor = (status) => {
    const statusColors = {
      'Submitted': 'blue',
      'Under Review': 'orange',
      'Quoted': 'purple',
      'Awaiting Payment': 'magenta',
      'Paid': 'green',
      'Clearing': 'green',
      'Cleared': 'green',

      'Delivered': 'green',
      'Closed': 'default'
    };
    return statusColors[status] || 'default';
  };

  const getStatusIcon = (status) => {
    const statusIcons = {
      'Submitted': <FileAddOutlined />,
      'Under Review': <ClockCircleOutlined />,
      'Quoted': <CalculatorOutlined />,
      'Awaiting Payment': <CreditCardOutlined />,
      'Paid': <CheckCircleOutlined />,
      'Clearing': <SyncOutlined />,
      'Cleared': <CheckCircleOutlined />,

      'Delivered': <CheckCircleFilled />,
      'Closed': <CheckCircleFilled />
    };
    return statusIcons[status] || <FileAddOutlined />;
  };

  const shipmentColumns = [
    {
      title: 'Tracking ID',
      dataIndex: 'trackingId',
      key: 'trackingId',
      render: (text) => <Text strong>{text}</Text>
    },
    {
      title: 'Client',
      key: 'client',
      render: (_, record) => (
        <div>
          <div style={{ fontWeight: 'bold' }}>{record.customer?.name || record.customerName}</div>
          <div style={{ fontSize: '12px', color: '#666' }}>
            {record.customer?.email || record.customerEmail || record.recipientPhone}
          </div>
        </div>
      )
    },
    {
      title: 'Goods',
      key: 'goods',
      render: (_, record) => (
        <div>
          <div>{record.packageType || record.goodsType}</div>
          <div style={{ fontSize: '12px', color: '#666' }}>
            GHS {(record.packageValue || record.value || 0).toLocaleString()}
          </div>
        </div>
      )
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (status) => (
        <Tag color={getStatusColor(status)} icon={getStatusIcon(status)}>
          {status}
        </Tag>
      )
    },
    {
      title: 'Created',
      dataIndex: 'createdAt',
      key: 'createdAt',
      render: (date) => date ? new Date(date).toLocaleDateString() : 'N/A'
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space size="small">
          <Button 
            type="text" 
            icon={<EyeOutlined />} 
            size="small" 
            onClick={() => navigate(`/shipments/${record.trackingId}`)}
          >
            View
          </Button>
        </Space>
      )
    }
  ];

  const getActivityIcon = (type) => {
    const icons = {
      'invoice': <FileTextOutlined style={{ color: '#1890ff' }} />,
      'eta': <GlobalOutlined style={{ color: '#52c41a' }} />,
      'enquiry': <FileAddOutlined style={{ color: '#00072D' }} />,
      'payment': <CreditCardOutlined style={{ color: '#52c41a' }} />
    };
    return icons[type] || <FileAddOutlined />;
  };

  if (loading) {
    return (
      <div style={{ padding: '24px', textAlign: 'center' }}>
        <Spin size="large" />
        <div style={{ marginTop: '16px' }}>
          <Text>Loading dashboard data...</Text>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: '24px' }}>
        <Alert
          message="Error Loading Dashboard"
          description={error}
          type="error"
          showIcon
          action={
            <Button size="small" onClick={loadDashboardData}>
              Retry
            </Button>
          }
        />
      </div>
    );
  }

  return (
    <div style={{ padding: '24px' }}>
      <div style={{ marginBottom: '24px' }}>
        <Title level={2}>Clearing Agent Dashboard</Title>
        <Text type="secondary">Monitor shipments, track status, and manage operations</Text>
      </div>

      {/* Statistics Cards */}
      <Row gutter={[16, 16]} style={{ marginBottom: '24px' }}>
        {stats.map((stat, index) => (
          <Col xs={24} sm={12} lg={6} key={index}>
            <Card>
              <Statistic
                title={stat.title}
                value={stat.value}
                prefix={stat.prefix}
                suffix={stat.suffix}
                valueStyle={{ color: stat.color }}
              />
            </Card>
          </Col>
        ))}
      </Row>

      <Row gutter={[16, 16]}>
        {/* Recent Shipments */}
        <Col xs={24} lg={16}>
          <Card 
            title="Recent Shipments" 
            extra={
              <Button 
                type="primary" 
                icon={<PlusOutlined />}
                onClick={() => navigate('/enquiries')}
              >
                New Job
              </Button>
            }
            style={{ marginBottom: '16px' }}
          >
            <Table
              dataSource={recentShipments} 
              columns={shipmentColumns} 
              pagination={false}
              size="small"
              locale={{
                emptyText: (
                  <Empty
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                    description={
                      <div>
                        <Text type="secondary" style={{ fontSize: '14px', marginBottom: '4px' }}>
                          No recent shipments
                        </Text>
                        <Text type="secondary" style={{ fontSize: '12px' }}>
                          Shipments will appear here as they are processed
                        </Text>
                      </div>
                    }
                  />
                )
              }}
            />
          </Card>
        </Col>

        {/* Workflow Status Overview */}
        <Col xs={24} lg={8}>
          <Card title="Workflow Status" style={{ marginBottom: '16px' }}>
            <Space direction="vertical" style={{ width: '100%' }}>
              {workflowStatuses.map((item, index) => (
                <div key={index} style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center',
                  padding: '8px 0'
                }}>
                  <Space>
                    <span style={{ color: item.color }}>{item.icon}</span>
                    <Text>{item.status}</Text>
                  </Space>
                  <Badge count={item.count} style={{ backgroundColor: item.color }} />
                </div>
              ))}
            </Space>
          </Card>

          {/* Recent Activities */}
          <Card title="Recent Activities">
            <Timeline size="small">
              {recentActivities.map((activity, index) => (
                <Timeline.Item 
                  key={index} 
                  dot={getActivityIcon(activity.type)}
                  color="blue"
                >
                  <div>
                    <Text strong>{activity.action}</Text>
                    <br />
                    <Text type="secondary" style={{ fontSize: '12px' }}>
                      {activity.time} • {activity.user}
                    </Text>
                  </div>
                </Timeline.Item>
              ))}
            </Timeline>
          </Card>
        </Col>
      </Row>

      {/* API Integration Test Section */}
      <Row gutter={[16, 16]} style={{ marginTop: '24px' }}>
        <Col span={24}>
          <IntegrationTest />
        </Col>
      </Row>
    </div>
  );
};

export default DashboardPage;
